      hu: ["1933-ban nyitott\\\\u00e1k meg.", "Eklektikus st\\\\u00edlusban \\\\u00e9p\\\\u00fclt.", "Az \\\\u00f3lom\\\\u00fcveg ablakok Conrado Sorgenicht munk\\\\u00e1i."],
